/**
 * Knowledge sheets: specs, usage, advantages and cautions per product.
 *
 * `corpus/sheets.json` is generated by scripts/build-sheets.ts from the
 * hand-written corpus/sheets/*.md. A sheet never holds a price — prices come
 * from the masterlist record for each code.
 */
import raw from '@/corpus/sheets.json';

export type Sheet = {
  slug: string;
  kind: 'model' | 'type';
  codes: string[];
  sources: string[];
  specs: { label: string; value: string }[];
  usage: string;
  advantages: string;
  cautions: string;
};

export const SHEETS = raw as Sheet[];

const BY_SHEET_CODE = new Map<string, Sheet>();
for (const s of SHEETS) for (const c of s.codes) BY_SHEET_CODE.set(c.toUpperCase(), s);

export function sheetForCode(code: string): Sheet | null {
  return BY_SHEET_CODE.get(code.trim().toUpperCase()) ?? null;
}
